import { ref, watch } from 'vue';

interface Result {
  id: number;
  name: string;
  email: string;
}

const FAKE_DATA: Result[] = [
  { id: 1, name: 'Alice Johnson', email: 'alice@example.com' },
  { id: 2, name: 'Bob Smith', email: 'bob@example.com' },
  { id: 3, name: 'Charlie Kim', email: 'charlie@example.com' },
  { id: 4, name: 'Diana Lopez', email: 'diana@example.com' },
  { id: 5, name: 'Ethan Brown', email: 'ethan@example.com' },
  { id: 6, name: 'Fiona Patel', email: 'fiona@example.com' }
];

function fakeApiSearch(term: string): Promise<Result[]> {
  const trimmed = term.trim().toLowerCase();
  const delayMs = 600;

  return new Promise((resolve, reject) => {
    window.setTimeout(() => {
      if (!trimmed) {
        resolve([]);
        return;
      }

      if (trimmed === 'error') {
        reject(new Error('Fake API error'));
        return;
      }

      const filtered = FAKE_DATA.filter((item) => {
        const name = item.name.toLowerCase();
        const mail = item.email.toLowerCase();
        return name.includes(trimmed) || mail.includes(trimmed);
      });

      resolve(filtered);
    }, delayMs);
  });
}

const query = ref('');
const results = ref<Result[]>([]);
const isLoading = ref(false);
const error = ref<string | null>(null);

let timeoutId: number | undefined;

watch(
  query,
  (value, _oldValue, onInvalidate) => {
    const trimmed = value.trim();

    if (timeoutId !== undefined) {
      window.clearTimeout(timeoutId);
      timeoutId = undefined;
    }

    if (!trimmed) {
      results.value = [];
      isLoading.value = false;
      error.value = null;
      return;
    }

    isLoading.value = true;
    error.value = null;

    // A response that arrives after the query changed again is ignored.
    let stale = false;
    timeoutId = window.setTimeout(() => {
      fakeApiSearch(trimmed)
        .then((data) => {
          if (stale) return;
          results.value = data;
          isLoading.value = false;
        })
        .catch((err) => {
          if (stale) return;
          results.value = [];
          isLoading.value = false;
          error.value = err instanceof Error ? err.message : 'Something went wrong.';
        });
    }, 500);

    onInvalidate(() => {
      stale = true;
      if (timeoutId !== undefined) {
        window.clearTimeout(timeoutId);
        timeoutId = undefined;
      }
    });
  }
);

const onInput = (event: Event) => {
  const target = event.target as HTMLInputElement;
  query.value = target.value;
};
